"use client";
import { motion, useScroll, useTransform } from "framer-motion";
import Link from "next/link";
import { useRef } from "react";

export default function Hero() {
    const containerRef = useRef(null);
    const { scrollYProgress } = useScroll({
        target: containerRef,
        offset: ["start start", "end start"]
    });

    const yTitle = useTransform(scrollYProgress, [0, 1], [0, 200]);
    const ySubtitle = useTransform(scrollYProgress, [0, 1], [0, 150]);
    const opacityHero = useTransform(scrollYProgress, [0, 0.8], [1, 0]);
    const scaleOrb = useTransform(scrollYProgress, [0, 1], [1, 1.5]);

    return (
        <section ref={containerRef} className="relative min-h-screen flex items-center justify-center overflow-hidden pt-20">

            {/* Background Gradients */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,rgba(124,58,237,0.1),transparent_50%)]" />
            <div className="absolute top-0 left-0 w-full h-full bg-[url('/grid.svg')] opacity-10" />

            {/* Animated Orbs */}
            <motion.div
                style={{ scale: scaleOrb }}
                animate={{
                    scale: [1, 1.2, 1],
                    opacity: [0.3, 0.5, 0.3],
                    backgroundColor: ["#7c3aed", "#db2777", "#06b6d4", "#7c3aed"]
                }}
                transition={{ duration: 12, repeat: Infinity }}
                className="absolute top-1/4 left-1/4 w-64 h-64 md:w-96 md:h-96 rounded-full blur-[80px] md:blur-[100px]"
            />
            <motion.div
                style={{ scale: scaleOrb }}
                animate={{
                    scale: [1, 1.2, 1],
                    opacity: [0.3, 0.5, 0.3],
                    backgroundColor: ["#06b6d4", "#7c3aed", "#db2777", "#06b6d4"]
                }}
                transition={{ duration: 15, repeat: Infinity, delay: 2 }}
                className="absolute bottom-1/4 right-1/4 w-64 h-64 md:w-96 md:h-96 rounded-full blur-[80px] md:blur-[100px]"
            />

            <motion.div
                style={{ opacity: opacityHero }}
                className="container mx-auto px-4 z-10 text-center"
            >
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.8 }}
                >
                    <motion.h1
                        style={{ y: yTitle }}
                        className="text-4xl sm:text-5xl md:text-7xl font-bold mb-8 tracking-[0.1em] text-wave leading-tight uppercase"
                        initial={{ filter: "blur(10px)", opacity: 0 }}
                        animate={{ filter: "blur(0px)", opacity: 1 }}
                        transition={{ duration: 1 }}
                    >
                        HEC ENTREPRENEURS
                    </motion.h1>

                    <motion.h2
                        style={{ y: ySubtitle }}
                        className="text-xl md:text-3xl font-semibold mb-8 text-white uppercase tracking-widest"
                    >
                        Des idées à l'impact
                    </motion.h2>

                    <motion.p
                        style={{ y: ySubtitle }}
                        className="text-lg md:text-2xl text-gray-400 max-w-3xl mx-auto mb-12 px-4"
                    >
                        Nous ne parlons pas d’entrepreneuriat. Nous le construisons.
                    </motion.p>

                    <div className="flex flex-col sm:flex-row gap-4 md:gap-6 justify-center items-center">
                        <Link href="/entrepreuneuriat" className="w-full sm:w-auto">
                            <button className="w-full sm:w-auto px-8 py-4 rounded-2xl bg-transparent border border-white/40 hover:bg-white/5 text-white font-light text-base backdrop-blur-sm transition-all tracking-[0.15em] uppercase">
                                Découvrir nos projets
                            </button>
                        </Link>
                        <Link href="/join" className="w-full sm:w-auto">
                            <button className="w-full sm:w-auto px-8 py-4 rounded-2xl bg-[#7c3aed] hover:bg-[#8b5cf6] text-white font-normal text-base transition-all hover:shadow-[0_0_30px_rgba(124,58,237,0.4)] tracking-[0.15em] uppercase">
                                Rejoindre le Club
                            </button>
                        </Link>
                    </div>
                </motion.div>
            </motion.div>
        </section>
    );
}

"use client";
import { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X } from "lucide-react";
import clsx from "clsx";

const links = [
    { href: "/", label: "Accueil" },
    { href: "/about", label: "À Propos" },
    { href: "/entrepreuneuriat", label: "Entrepreuneuriat" },
    { href: "/resources", label: "Ressources" },
    { href: "/team-up", label: "Team Up" },
];

export default function Navbar() {
    const pathname = usePathname();
    const [isOpen, setIsOpen] = useState(false);

    return (
        <motion.nav
            initial={{ y: -100 }}
            animate={{ y: 0 }}
            className="fixed top-0 left-0 right-0 z-50 pt-6 px-4"
        >
            {/* Corner Logos */}
            <div className="absolute top-4 left-4 sm:top-6 sm:left-8 items-center flex">
                <img src="/logo-ihec.png" alt="IHEC Carthage" className="h-12 sm:h-24 md:h-32 w-auto opacity-100 transition-opacity" />
            </div>
            <div className="absolute top-4 right-4 sm:top-6 sm:right-8 items-center flex">
                <img src="/logo-club.png" alt="HEC Entrepreneurs" className="h-12 sm:h-24 md:h-32 w-auto opacity-100 transition-opacity" />
            </div>

            <div className="flex justify-center">
                <div className="glass px-2 py-2 rounded-full flex items-center gap-1 relative">
                    {/* Desktop Links */}
                    <div className="hidden md:flex items-center gap-1">
                        {links.map((link) => (
                            <Link
                                key={link.href}
                                href={link.href}
                                className={clsx(
                                    "relative px-4 py-2 rounded-full text-sm font-light tracking-widest transition-colors",
                                    pathname === link.href ? "text-white" : "text-gray-400 hover:text-white"
                                )}
                            >
                                {pathname === link.href && (
                                    <motion.div
                                        layoutId="navbar-indicator"
                                        className="absolute inset-0 bg-primary/20 rounded-full border border-primary/50"
                                        transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
                                    />
                                )}
                                <span className="relative z-10">{link.label}</span>
                            </Link>
                        ))}
                    </div>

                    {/* Mobile Toggle */}
                    <button
                        onClick={() => setIsOpen(!isOpen)}
                        className="md:hidden p-2 text-gray-400 hover:text-white transition-colors"
                    >
                        {isOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
                    </button>

                    {/* Mobile Menu */}
                    <AnimatePresence>
                        {isOpen && (
                            <motion.div
                                initial={{ opacity: 0, scale: 0.95, y: 10, x: "-50%" }}
                                animate={{ opacity: 1, scale: 1, y: 0, x: "-50%" }}
                                exit={{ opacity: 0, scale: 0.95, y: 10, x: "-50%" }}
                                className="absolute top-full left-1/2 mt-4 p-2 glass rounded-[2rem] border border-primary/20 md:hidden flex flex-col gap-1 w-[280px] shadow-2xl"
                            >
                                {links.map((link) => (
                                    <Link
                                        key={link.href}
                                        href={link.href}
                                        onClick={() => setIsOpen(false)}
                                        className={clsx(
                                            "px-6 py-3 rounded-2xl text-xs font-light uppercase tracking-[0.1em] transition-all text-center",
                                            pathname === link.href
                                                ? "bg-primary/20 text-primary border border-primary/30"
                                                : "text-gray-400 hover:text-white hover:bg-white/5"
                                        )}
                                    >
                                        {link.label}
                                    </Link>
                                ))}
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>
        </motion.nav>
    );
}

